const PACKAGE_NAME = 'usage-dashboard'

export const name = 'usage-dashboard-autoload'
export const inject = ['agents', 'dynamicCordisRunner']

export function apply(ctx) {
  const agents = ctx.agents
  const runner = ctx.dynamicCordisRunner
  const install = (agent) => {
    // Subagent children are skipped: the root session's dashboard folds
    // every session globally (global event listeners), so a per-child
    // package would only duplicate writers.
    if (agent.owner !== undefined) return
    try {
      if (runner.listPlugins(agent).some(plugin => plugin.name === PACKAGE_NAME)) return
      const receipt = runner.define({
        sessionId: agent.id,
        plugin: { kind: 'new', idPrefix: 'usage' },
        name: PACKAGE_NAME,
        purpose: 'Durable cross-session usage ledger and sidebar dashboard (auto-installed by dsh-usage-dashboard-autoload)',
        code: { host: HOST_CODE, client: CLIENT_CODE },
      })
      void runner.run(agent, receipt.pluginId, receipt.packageId, 'run').then(
        (response) => {
          console.log(`[usage-dashboard-autoload] ${receipt.pluginId}/${receipt.packageId} -> ${response.status}`)
        },
        (error) => {
          console.error(`[usage-dashboard-autoload] run for ${agent.id} failed: ${String(error)}`)
        },
      )
    } catch (error) {
      console.error(`[usage-dashboard-autoload] install for ${agent.id} failed: ${String(error)}`)
    }
  }
  ctx.on('agent/created', ({ agent }) => { install(agent) }, { global: true })
  for (const agent of agents.list()) install(agent)
}
